// Dialect v0.6 expressions: grammar, folding and policy analysis, checked against the Python reference
// (drivers/expr_vectors.json, generated by drivers/gen_expr_vectors.py) and the Python parser tests.
// No server needed.
import test from "node:test";
import assert from "node:assert/strict";
import * as fs from "fs";
import {
  parseExpression, analyzeExpression, renderExpr, scopeResolver, frac, Expr, ExprColumn, MAX_EXPR_HEIGHT,
} from "../src/expr";
import { TorusError } from "../src/errors";
import { EXPR_VECTORS } from "./helpers";

const vec = JSON.parse(fs.readFileSync(EXPR_VECTORS, "utf8"));

const kind = (k: string) => (e: unknown) => e instanceof TorusError && e.kind === k;

function scopeOf(name: string) {
  return scopeResolver((vec.scopes[name] as Array<[string, Array<[string, string, string]>]>).map(
    ([alias, cols]) => [alias, cols.map(([n, t, p]): ExprColumn => ({ name: n, type: t, policy: p }))] as [string, ExprColumn[]]));
}

test("static vectors: every expression is accepted or rejected exactly like the Python reference", () => {
  let n = 0;
  for (const c of vec.static) {
    const where = `${c.scope}: ${JSON.stringify(c.expr).slice(0, 80)}`;
    const resolve = scopeOf(c.scope);
    const run = () => {
      const tree = parseExpression(c.expr);
      return analyzeExpression(tree, (r) => resolve(r).col);
    };
    if (c.error === "ParseError") {
      assert.throws(run, kind("ParseError"), where);
    } else if (c.error === "PlanError") {
      assert.throws(run, (e: unknown) => e instanceof TorusError && e.kind === "PlanError" && e.message === c.message, where);
    } else {
      const { expr, info } = run();
      assert.equal(info.text, c.text, where);
      assert.equal(info.kind, c.kind, where);
      assert.equal(info.enc, c.enc, where);
      assert.equal(info.depth, c.depth, where);
      assert.equal(info.ctMuls, c.ct_muls, where);
      assert.equal(info.inversions, c.inversions, where);
      assert.equal(renderExpr(expr), c.text, where);
    }
    n++;
  }
  assert.ok(n > 400, `only ${n} static vectors`);
});

// ── the Python parser tests (parser/tests/test_expr.py), on the AST ──
const C = (name: string): Expr => ({ t: "col", name });
const L = (n: number, d = 1): Expr => ({ t: "lit", v: frac(BigInt(n), BigInt(d)) });
const B = (op: "+" | "-" | "*" | "/", l: Expr, r: Expr): Expr => ({ t: "bin", op, l, r });
const NEG = (e: Expr): Expr => ({ t: "neg", e });
const AGG = (fn: "SUM" | "AVG" | "COUNT", arg: Expr | null = null): Expr => ({ t: "agg", fn, arg });
const p = parseExpression;

test("precedence and left associativity", () => {
  assert.deepEqual(p("a+b*c"), B("+", C("a"), B("*", C("b"), C("c"))));
  assert.deepEqual(p("a-b-c"), B("-", B("-", C("a"), C("b")), C("c")));
  assert.deepEqual(p("a/b/c"), B("/", B("/", C("a"), C("b")), C("c")));
  assert.deepEqual(p("a*b/c"), B("/", B("*", C("a"), C("b")), C("c")));
  assert.deepEqual(p("(a+b)*c"), B("*", B("+", C("a"), C("b")), C("c")));
  assert.deepEqual(p("a*b*c"), B("*", B("*", C("a"), C("b")), C("c")));
});

test("unary minus and signed literals", () => {
  assert.deepEqual(p("-a"), NEG(C("a")));
  assert.deepEqual(p("-(a+b)"), NEG(B("+", C("a"), C("b"))));
  assert.deepEqual(p("a * -b"), B("*", C("a"), NEG(C("b"))));
  assert.deepEqual(p("a - -1"), B("-", C("a"), L(-1)));
  assert.deepEqual(p("a*-2"), B("*", C("a"), L(-2)));
  assert.deepEqual(p("-(-a)"), NEG(NEG(C("a"))));
  assert.deepEqual(p("- 3 * a + b"), B("+", B("*", L(-3), C("a")), C("b")));
});

test("a negative literal token in operator position is a subtraction", () => {
  for (const t of ["a-1", "a -1", "a - 1", "a-1*b", "x*y-2", "(a)-1"]) {
    const e = p(t);
    assert.ok(e.t === "bin" && e.op === "-", t);
  }
  assert.deepEqual(p("a-2*b"), B("-", C("a"), B("*", L(2), C("b"))));
  assert.deepEqual(p("a--1"), C("a"));            // `--` starts a comment, as in SQL
});

test("fraction and integer literals, aggregates", () => {
  assert.deepEqual(p("a / FRAC(2, 3)"), B("/", C("a"), L(2, 3)));
  assert.deepEqual(p("a + FRAC(4, 2)"), B("+", C("a"), L(2)));
  assert.throws(() => p("a + FRAC(1, 0)"), kind("ParseError"));
  assert.deepEqual(p("SUM(a*b)/COUNT(*)"), B("/", AGG("SUM", B("*", C("a"), C("b"))), AGG("COUNT")));
  assert.deepEqual(p("AVG(a+1)*2"), B("*", AGG("AVG", B("+", C("a"), L(1))), L(2)));
  assert.deepEqual(p("t.a*t.b"), B("*", C("t.a"), C("t.b")));
});

test("malformed expressions are ParseErrors", () => {
  for (const t of ["a+", "(a", "a b", "a+*b", "sqrt(a)", "MIN(a)+1", "1+DOT(a,b)", "SUM(SUM(a))", "SUM(a+COUNT(*))",
    "COUNT(a)", "a,", "", "a/", "SUM()", "a;", "'x'", "a % b", "a ^ b", "FROM", "a FROM t", "a AS b"]) {
    assert.throws(() => p(t), kind("ParseError"), JSON.stringify(t));
  }
});

test("the expression height is bounded and deep input cannot overflow the stack", () => {
  p("a" + "+a".repeat(98));                                       // height 98: fine
  assert.equal(MAX_EXPR_HEIGHT, 100);
  const deep = (t: string) => assert.throws(() => p(t), (e: unknown) => e instanceof TorusError && e.kind === "ParseError" && /nested too deeply/.test(e.message));
  deep("a+".repeat(200) + "a");
  deep("(".repeat(150) + "a" + ")".repeat(150) + " + a".repeat(150));
  deep("- ".repeat(300) + "a");
  deep("(".repeat(100000) + "a");
  deep("- ".repeat(100000) + "a");
  deep("SUM(".repeat(1000) + "a");
});

test("render round-trips through the parser", () => {
  let seed = 5;
  const rnd = () => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed / 0x7fffffff; };
  const gen = (d: number): Expr => {
    if (d === 0 || rnd() < 0.2) {
      const k = Math.floor(rnd() * 4);
      return [C("a"), C("b"), C("t.c"), L([2, 7, -3][Math.floor(rnd() * 3)])][k];
    }
    if (rnd() < 0.15) { const x = gen(d - 1); return x.t === "lit" ? { t: "lit", v: { num: -x.v.num, den: x.v.den } } : NEG(x); }
    return B("+-*/"[Math.floor(rnd() * 4)] as "+", gen(d - 1), gen(d - 1));
  };
  let checked = 0;
  for (let i = 0; i < 300; i++) {
    const e = gen(4);
    if (e.t === "col" || e.t === "lit") continue;
    const text = renderExpr(e);
    assert.equal(renderExpr(p(text)), text, text);
    checked++;
  }
  assert.ok(checked > 200);
});

test("constants are folded exactly", () => {
  const resolve = scopeResolver([["t", [{ name: "p", type: "int", policy: "paired" }]]]);
  const { expr } = analyzeExpression(p("p / (1/3 + FRAC(1,6))"), (r) => resolve(r).col);
  assert.deepEqual(expr, B("/", C("p"), L(1, 2)));
});

test("the JSON vectors file is the one the Python generator wrote", () => {
  assert.equal(typeof vec.comment, "string");
  assert.ok(vec.exec.cases.length > 400);
});
